svg.script:
const SVGNS = "http:/" + "/www.w3.org/2000/svg";
const XHTML = "http:/" + "/www.w3.org/1999/xhtml";
const BASE  = "https:/" + "/cdn.jsdelivr.net/gh/jaromaz/jslinux-mobile@master/";

const root = document.documentElement;
root.setAttribute("xmlns", SVGNS);

const fo = document.createElementNS(SVGNS, "foreignObject");
fo.setAttribute("x", "0");
fo.setAttribute("y", "0");
fo.setAttribute("width", "100%");
fo.setAttribute("height", "100%");

const app = document.createElementNS(XHTML, "div");
app.id = "app";
app.style.cssText = "width:100vw;height:100vh;margin:0;padding:0;background:#000;color:#0f0;font-family:monospace;";
app.innerHTML = '<div id="status" style="padding:16px;">Booting JSLinux Mobile...</div>';

fo.appendChild(app);
root.appendChild(fo);

const baseEl = document.createElementNS(XHTML, "base");
baseEl.setAttribute("href", BASE);
root.insertBefore(baseEl, root.firstChild);

fetch(BASE + "index.html")
  .then(res => {
    if (!res.ok) throw new Error("HTTP " + res.status);
    return res.text();
  })
  .then(html => {
    const doc = new DOMParser().parseFromString(html, "text/html");
    app.innerHTML = "";

    doc.querySelectorAll("link[rel='stylesheet'], style").forEach(el => {
      app.appendChild(document.importNode(el, true));
    });

    Array.from(doc.body.childNodes).forEach(node => {
      if (node.nodeName !== "SCRIPT") {
        app.appendChild(document.importNode(node, true));
      }
    });

    const scripts = Array.from(doc.querySelectorAll("script"));
    (function runNext(i) {
      if (i >= scripts.length) {
        if (typeof window.onload === "function") window.onload();
        return;
      }
      const oldScript = scripts[i];
      const newScript = document.createElementNS(SVGNS, "script");
      if (oldScript.src) {
        newScript.setAttribute("href", BASE + oldScript.getAttribute("src"));
        newScript.onload = () => runNext(i + 1);
        newScript.onerror = () => runNext(i + 1);
      } else {
        newScript.textContent = oldScript.textContent;
        runNext(i + 1);
      }
      root.appendChild(newScript);
    })(0);
  })
  .catch(err => {
    const st = document.getElementById("status");
    if (st) st.textContent = "Error: " + err.message;
  });
